def canonical_json_sha256(value: Any) -> str:
    """Return the canonical JSON digest of *value*."""
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


