def _rgb_pixel_sha256(image: Image.Image) -> str:
    """Return the normalized RGB pixel digest of *image*."""
    normalized = ImageOps.exif_transpose(image).convert("RGB")
    return hashlib.sha256(normalized.tobytes()).hexdigest()


def _marker_rgb_medians(signature: Mapping[str, Any]) -> list[list[int]]:
    cells = list(signature.get("rgb_cells") or [])
    return [
        [int(value) for value in list(cell.get("median_rgb") or [])[:3]]
        for cell in cells
        if isinstance(cell, Mapping)
    ]


def _media_row(path: Path, root: Path) -> dict[str, Any]:
    """Describe one stored photo by its pixels and its identity marker."""
    row = {
        "path": path,
        "relative_path": relative_media_path(path, root),
        "readable": False,
        "read_error": None,
        "dimensions": None,
        "rgb_pixel_sha256": None,
        "marker_detected": False,
        "marker_index": None,
        "detection_score": None,
        "identity_confidence": None,
        "marker_box": None,
        "marker_rgb_medians": [],
    }
    try:
        with Image.open(path) as handle:
            handle.load()
            normalized = ImageOps.exif_transpose(handle).convert("RGB")
            row["readable"] = True
            row["dimensions"] = list(normalized.size)
            row["rgb_pixel_sha256"] = _rgb_pixel_sha256(normalized)
            detection = detect_rgb_marker(normalized)
    except Exception as exc:
        row["read_error"] = f"{type(exc).__name__}: {exc}"
        return row
    if detection is not None:
        signature = detection.get("signature")
        row.update(
            {
                "marker_detected": True,
                "marker_index": detection.get("marker_index"),
                "detection_score": detection.get("score"),
                "identity_confidence": detection.get("identity_confidence"),
                "marker_box": list(detection.get("box") or []),
                "marker_rgb_medians": _marker_rgb_medians(
                    signature if isinstance(signature, Mapping) else {}
                ),
            }
        )
    return row


def read_simulator_library(simulator_root: Path) -> list[dict[str, Any]]:
    """Describe every stored photo below *simulator_root*."""
    return [_media_row(path, simulator_root) for path in simulator_media_files(simulator_root)]


def _locate_export(
    golden: Mapping[str, Any], rows: Sequence[Mapping[str, Any]]
) -> tuple[Mapping[str, Any] | None, list[str]]:
    """Return the one row whose pixels are the expected export, plus its matches."""
    digest = str(golden["rgb_pixel_sha256"])
    matches = [row for row in rows if row.get("rgb_pixel_sha256") == digest]
    names = [str(row.get("relative_path")) for row in matches]
    if len(matches) == 1:
        return matches[0], names
    return None, names


def validate_exports(rows: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    """Judge the expected exports from the stored photo library alone."""
    checks = []
    failures = []
    per_export = []

    def record(label, passed, expected, observed, reason):
        checks.append(
            {
                "label": label,
                "passed": bool(passed),
                "expected": expected,
                "observed": observed,
            }
        )
        if not passed:
            failures.append(
                {
                    "check": label,
                    "expected": expected,
                    "observed": observed,
                    "reason": reason,
                }
            )

    matched_paths = []
    matched_markers = []
    for golden in GOLDEN_EXPORTS:
        marker = int(golden["marker_index"])
        asset = str(golden["asset_id"])
        row, matches = _locate_export(golden, rows)
        if row is not None:
            matched_paths.append(str(row.get("relative_path")))
            matched_markers.append(row.get("marker_index"))
        expected_report = {
            "asset_id": asset,
            "marker_index": marker,
            "dimensions": list(golden["dimensions"]),
            "marker_box": list(golden["marker_box"]),
            "revision": golden.get("revision"),
            "rgb_pixel_sha256": golden["rgb_pixel_sha256"],
        }
        observed_report = {
            "relative_path": None if row is None else row.get("relative_path"),
            "matches": matches,
            "dimensions": None if row is None else row.get("dimensions"),
            "rgb_pixel_sha256": None if row is None else row.get("rgb_pixel_sha256"),
            "marker_detected": False if row is None else bool(row.get("marker_detected")),
            "marker_index": None if row is None else row.get("marker_index"),
            "detection_score": None if row is None else row.get("detection_score"),
            "identity_confidence": None if row is None else row.get("identity_confidence"),
            "marker_box": None if row is None else row.get("marker_box"),
            "marker_rgb_medians": [] if row is None else list(row.get("marker_rgb_medians") or []),
            "read_error": None if row is None else row.get("read_error"),
        }
        if row is None:
            record(
                f"export.marker{marker}.{asset}.image_found",
                False,
                {"rgb_pixel_sha256": golden["rgb_pixel_sha256"]},
                {"matches": matches},
                "EXPORT_MISSING",
            )
            per_export.append(
                {
                    "marker_index": marker,
                    "asset_id": asset,
                    "expected": expected_report,
                    "observed": observed_report,
                    "status": "FAIL",
                }
            )
            continue
        row_checks = (
            (
                "image_found",
                True,
                {"relative_to": "Media/DCIM"},
                row.get("relative_path"),
                "EXPORT_MISSING",
            ),
            (
                "png_export",
                str(row.get("relative_path") or "").upper().endswith(".PNG"),
                ".PNG export",
                row.get("relative_path"),
                "EXPORT_NOT_PNG",
            ),
            (
                "dimensions",
                list(row.get("dimensions") or []) == list(golden["dimensions"]),
                list(golden["dimensions"]),
                row.get("dimensions"),
                "EXPORT_DIMENSIONS_MISMATCH",
            ),
            (
                "rgb_pixel_sha256",
                row.get("rgb_pixel_sha256") == golden["rgb_pixel_sha256"],
                golden["rgb_pixel_sha256"],
                row.get("rgb_pixel_sha256"),
                "EXPORT_PIXELS_MISMATCH",
            ),
            (
                "marker_detected",
                bool(row.get("marker_detected")),
                {"minimum_detection_score": MIN_DETECTION_SCORE},
                {
                    "marker_detected": row.get("marker_detected"),
                    "detection_score": row.get("detection_score"),
                },
                "EXPORT_MARKER_MISSING",
            ),
            (
                "detection_score",
                float(row.get("detection_score") or 0.0) >= MIN_DETECTION_SCORE,
                MIN_DETECTION_SCORE,
                row.get("detection_score"),
                "EXPORT_MARKER_SCORE_BELOW_MINIMUM",
            ),
            (
                "identity_confidence",
                float(row.get("identity_confidence") or 0.0) >= MIN_IDENTITY_CONFIDENCE,
                MIN_IDENTITY_CONFIDENCE,
                row.get("identity_confidence"),
                "EXPORT_MARKER_IDENTITY_UNCONFIRMED",
            ),
            (
                "identity",
                row.get("marker_index") == marker,
                {"marker_index": marker, "asset_id": asset},
                {
                    "marker_index": row.get("marker_index"),
                    "marker_box": row.get("marker_box"),
                },
                "EXPORT_MARKER_IDENTITY_MISMATCH",
            ),
        )
        for field, passed, expected, observed, reason in row_checks:
            record(f"export.marker{marker}.{asset}.{field}", passed, expected, observed, reason)
        per_export.append(
            {
                "marker_index": marker,
                "asset_id": asset,
                "expected": expected_report,
                "observed": observed_report,
                "status": "PASS" if all(item[1] for item in row_checks) else "FAIL",
            }
        )

    golden_digests = [str(golden["rgb_pixel_sha256"]) for golden in GOLDEN_EXPORTS]
    count_per_digest = [
        sum(1 for row in rows if row.get("rgb_pixel_sha256") == digest)
        for digest in golden_digests
    ]
    record(
        "output.exact_count",
        all(count == 1 for count in count_per_digest),
        "one stored photo per expected export",
        {"matches_per_export": count_per_digest, "matched_paths": matched_paths},
        "EXTRA_OR_MISSING_OUTPUT",
    )
    record(
        "output.exact_one_per_marker",
        sorted(marker for marker in matched_markers if isinstance(marker, int))
        == sorted(int(golden["marker_index"]) for golden in GOLDEN_EXPORTS),
        sorted(int(golden["marker_index"]) for golden in GOLDEN_EXPORTS),
        sorted(marker for marker in matched_markers if isinstance(marker, int)),
        "MISSING_DUPLICATE_OR_UNKNOWN_MARKER",
    )
    record(
        "output.unique_export_pixels",
        len(set(matched_paths)) == len(matched_paths) and all(matched_paths),
        "distinct stored photos",
        matched_paths,
        "DUPLICATE_OUTPUT_PATH",
    )
    expected_sides = {
        tuple(int(value) for value in golden["dimensions"]) for golden in GOLDEN_EXPORTS
    }
    unexpected_rows = [
        row.get("relative_path")
        for row in rows
        if tuple(row.get("dimensions") or ()) in expected_sides
        and row.get("rgb_pixel_sha256") not in golden_digests
    ]
    record(
        "output.no_unexpected_export",
        not unexpected_rows,
        "no undeclared image sharing the export dimensions",
        unexpected_rows,
        "UNDECLARED_EXPORT_PRESENT",
    )
    record(
        "output.all_media_readable",
        all(row.get("readable") for row in rows),
        "every stored photo opens",
        [
            {"relative_path": row.get("relative_path"), "read_error": row.get("read_error")}
            for row in rows
            if not row.get("readable")
        ],
        "UNREADABLE_STORED_PHOTO",
    )

    return {
        "status": "PASS" if not failures else "FAIL",
        "checks": checks,
        "failures": failures,
        "exports": per_export,
        "media_count": len(rows),
        "media": [
            {
                "relative_path": row.get("relative_path"),
                "dimensions": row.get("dimensions"),
                "rgb_pixel_sha256": row.get("rgb_pixel_sha256"),
                "marker_index": row.get("marker_index"),
                "detection_score": row.get("detection_score"),
                "identity_confidence": row.get("identity_confidence"),
                "marker_box": row.get("marker_box"),
                "marker_rgb_medians": row.get("marker_rgb_medians"),
                "read_error": row.get("read_error"),
            }
            for row in rows
        ],
    }


class OpenPhotoEditMusicMediaPortraitsFourExports186365Evaluator(BaseEvaluator):
    """Judging the four marked exports of the music media portrait task."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        binding_failures = self._binding_failures(params)
        if binding_failures:
            return self._result(
                EvalStatus.ERROR,
                "OpenPhotoEdit evaluator binding mismatch",
                {
                    "status": "ERROR",
                    "checks": [{"label": "binding", "passed": False}],
                    "failures": binding_failures,
                    "expected": RUNTIME_PARAMETERS,
                    "observed": params,
                },
            )
        udid = str(params.get("udid") or "").strip()
        simulator_root = Path.home() / DEVICE_ROOT / udid / "data"
        if not udid or not simulator_root.is_dir():
            return self._result(
                EvalStatus.ERROR,
                "OpenPhotoEdit simulator photo library is unavailable",
                {
                    "status": "ERROR",
                    "checks": [
                        {
                            "label": "simulator.data_root",
                            "passed": False,
                            "observed": str(simulator_root),
                        }
                    ],
                    "failures": [
                        {
                            "check": "simulator.data_root",
                            "reason": "SIMULATOR_DEVICE_DATA_UNAVAILABLE",
                            "expected": "a readable simulator device data directory",
                            "observed": str(simulator_root),
                        }
                    ],
                    "observed": {"udid_present": bool(udid)},
                },
            )
        try:
            rows = read_simulator_library(simulator_root)
            evidence = validate_exports(rows)
        except Exception as exc:
            return self._result(
                EvalStatus.ERROR,
                "OpenPhotoEdit export verification could not complete: "
                f"{type(exc).__name__}: {exc}",
                {
                    "status": "ERROR",
                    "checks": [{"label": "library.read", "passed": False}],
                    "failures": [
                        {
                            "check": "library.read",
                            "reason": "LIBRARY_READ_ERROR",
                            "exception_type": type(exc).__name__,
                            "message": str(exc),
                        }
                    ],
                    "observed": {"simulator_root": str(simulator_root)},
                },
            )
        evidence["simulator_root"] = str(simulator_root)
        status = EvalStatus.PASS if evidence["status"] == "PASS" else EvalStatus.FAIL
        message = "OpenPhotoEdit music media portraits: four exports match the declared pixels and marker identities" if status == EvalStatus.PASS else "OpenPhotoEdit music media portraits: export verification failed"
        return self._result(status, message, evidence)

    @staticmethod
    def _binding_failures(params: Mapping[str, Any]) -> list[dict[str, Any]]:
        return [
            {
                "field": field,
                "expected": value,
                "observed": params.get(field),
                "reason": "BINDING_MISMATCH",
            }
            for field, value in RUNTIME_PARAMETERS.items()
            if params.get(field) != value
        ]

    @staticmethod
    def _result(status: EvalStatus, message: str, evidence: Mapping[str, Any]) -> EvalResult:
        return EvalResult(
            status=status,
            message=message,
            metadata={
                "read_only": True,
                "task_id": TASK_ID,
                "instruction_sha256": INSTRUCTION_SHA256,
                "ruleset_sha256": RULESET_SHA256,
                "output_contract": "four marked exports judged by normalized RGB pixel digest",
                "expected": {
                    "exports": [
                        {
                            "marker_index": golden["marker_index"],
                            "asset_id": golden["asset_id"],
                            "dimensions": list(golden["dimensions"]),
                            "marker_box": list(golden["marker_box"]),
                            "revision": golden.get("revision"),
                            "rgb_pixel_sha256": golden["rgb_pixel_sha256"],
                        }
                        for golden in GOLDEN_EXPORTS
                    ]
                },
                "observed": {
                    "media_count": evidence.get("media_count"),
                    "media": list(evidence.get("media") or []),
                },
                "checks": list(evidence.get("checks") or []),
                "failures": list(evidence.get("failures") or []),
                "exports": list(evidence.get("exports") or []),
                "media_count": evidence.get("media_count"),
                "media": list(evidence.get("media") or []),
                "simulator_root": evidence.get("simulator_root"),
                "evidence": dict(evidence),
                "safety": {
                    "appium_session_created": False,
                    "app_launched": False,
                    "gui_action_executed": False,
                    "simulator_state_changed": False,
                    "media_changed": False,
                    "photo_library_read_only": True,
                },
            },
        )
